'use strict';
/* public/js/60-title.js -- title screen, camp password, session save/resume, start-game flow. Generated by scripts/split-client.mjs; see ARCHITECTURE.md. */
/* ---------- title / start ---------- */
const NICKS=['Caveman','Sploosh','Big Thumb','Onion Boy','Lizard Bait','Seeds','Barf Bag','Twitch','Theodore','Sweet Feet'];
const nickIn=$('#nick');
try{nickIn.value=localStorage.getItem('cgl-nick')||NICKS[Math.floor(Math.random()*NICKS.length)]}catch(e){nickIn.value=NICKS[Math.floor(Math.random()*NICKS.length)]}
function cleanName(s){return String(s||'').replace(/[^\p{L}\p{N} _'.-]/gu,'').trim().slice(0,16)}
const SAVE_KEYS=['bucket','hopper','pipe','dynamite','water','sack','onions','tonic','medkit','up','hasKB','reported','holesDone','name','color','detOn','batt'];   /* no 'seeds': gold is the crew wallet's (84-wallet.js) */
function saveSession(newDay){
  if(!S.started)return;
  try{const o={at:Date.now(),S:{},P:{x:P.x,z:P.z,yaw:P.yaw,pitch:P.pitch,room:S.tent}};for(const k of SAVE_KEYS)o.S[k]=S[k];if(newDay){o.S.hasKB=false;o.S.reported=false}
    sessionStorage.setItem('cgl-session',JSON.stringify(o))}catch(e){}
}
setInterval(saveSession,2000);addEventListener('pagehide',()=>saveSession());
function loadSession(){try{const o=JSON.parse(sessionStorage.getItem('cgl-session')||'null');if(o&&o.S&&Date.now()-o.at<30*60*1000)return o}catch(e){}return null}
function startGame(resume){
  if(SETTINGS.voiceOn&&!VOX.enabled)setVoiceEnabled(true).then(()=>{if(!VOX.enabled)rememberVoice()});   // voice was on last time: back on (mic denied now: remembered as off)
  if(S.started)return;
  if(resume&&resume.S){
    const r=resume.S;S.resumed=true;
    S.bucket=num(r.bucket,0,20,0);S.hopper=num(r.hopper,0,120,0);S.pipe=num(r.pipe,0,999,0)|0;S.dynamite=num(r.dynamite,0,99,0)|0;S.water=num(r.water,0,180,100);S.onions=num(r.onions,0,999,0)|0;S.tonic=num(r.tonic,0,99,0)|0;S.medkit=num(r.medkit,0,99,0)|0;S.holesDone=num(r.holesDone,0,1e5,0)|0;
    S.sack=Array.isArray(r.sack)?r.sack.filter(t=>LOOT[t]&&!LOOT[t].key).slice(0,200):[];
    S.up={};if(r.up&&typeof r.up==='object')for(const k of ['shovel','pan','bucket','spade','long','detector','canteen','canteen3','bucket2','bucket3','hopper','hopper2','hopper3','disarm','dog','grav','grapple','goldShovel','bigsack','rope','walkie'])if(r.up[k])S.up[k]=true;S.batt=num(r.batt,0,100,100);
    S.hasKB=!!r.hasKB;S.reported=!!r.reported;S.detOn=r.detOn!==false;nickIn.value=r.name||nickIn.value;
    const p=resume.P||{};P.x=num(p.x,-HALF+3,HALF-3,0);P.z=num(p.z,-HALF+3,HALF-3,39);P.y=groundAt(P.x,P.z);P.yaw=num(p.yaw,-100,100,0);P.pitch=num(p.pitch,-0.15,1.25,0.32);
    if(Number.isInteger(p.room)&&TENTS[p.room]){
      const t=TENTS[p.room];S.tent=p.room;S.tentBack={x:t.x,z:t.z-t.hd-1.3};
      P.x=clamp(P.x,t.x-t.roomW+0.5,t.x+t.roomW-0.5);P.z=clamp(P.z,t.z-t.roomD+0.5,t.z+t.roomD-0.5);P.y=TENT_FLOOR_Y;
      ROOM_MESHES[p.room].visible=true;ROOM_LIGHTS[p.room].visible=true;
    }
  }
  S.name=cleanName(nickIn.value)||'Caveman';try{localStorage.setItem('cgl-nick',S.name)}catch(e){}
  S.color=resume&&resume.S&&Number.isInteger(resume.S.color)?clamp(resume.S.color,0,CAMPER_COLORS.length-1):Math.floor(hash2(S.name.length*31+S.name.charCodeAt(0),Date.now()%9973)*CAMPER_COLORS.length);
  me=makePerson(Object.assign(playerLook(S.name,S.color),{suit:JUMPSUITS[mySuit()].c}));scene.add(me.g);me.suitIdx=mySuit();me.ward=MY_WARD;   // jumpsuit colour: 81-badges.js
  meL=makeLabel(me.g,S.name+' (you)','');loadProg();loadRun();meL.n.textContent=myTag();setHat(me,myLevel());
  $('#hudName').textContent=S.name;
  $('#title').hidden=true;$('#hud').hidden=false;S.started=true;initAudio();applyVolume();
  if(!S.resumed){P.yaw=0;P.fa=Math.PI}
  if(S.revealed===false&&S.reported)reveal('You');
  lockMouse();
  if(S.resumed){toast('Welcome back to camp. Your progress was saved.','good',3500)}
  else{setTimeout(()=>say(clerkL,'There\'s gold in that lake bed. Fill your bucket and bring it to the sifter.',6000),800);
  setTimeout(()=>toast('Walk out onto the lake bed and hold click to dig. Every scoop fills your bucket with sand; sift it at camp for gold.','',6500),1500)}
  sendJoin();
}
const campIn=$('#campPass'),campWrap=$('#campWrap'),campErr=$('#campErr'),startBtn=$('#startBtn');
function showCampErr(msg){campErr.textContent=msg;campErr.hidden=false}
function hideCampErr(){campErr.hidden=true}
function cleanPass(s){return String(s||'').replace(/[\u0000-\u001f\u007f]/g,'').trim().slice(0,64)}
startBtn.onclick=()=>{
  if(net.needPass&&!net.passOk){
    const p=cleanPass(campIn.value);
    if(!p){showCampErr('Enter the camp password.');return}
    PASS=p;net.awaitingJoin=true;hideCampErr();showCampErr('Checking…');
    wsSend({t:'join',n:cleanName(nickIn.value)||'Caveman',v:2,host:HOST||undefined,p:PASS});
    return;
  }
  startGame();
};
addEventListener('pointerdown',()=>{if(AC&&AC.state==='suspended')AC.resume()});
// Belt-and-suspenders: if the socket never tells us whether a password is needed (server down, odd network),
// don't leave the Start button, or a pending session resume, stuck waiting forever.
setTimeout(()=>{startBtn.disabled=false;maybeResume()},4200);
